describe('Currency Field Formatting', () => {
    beforeEach(() => {
        cy.visit('/your-form-page'); // Replace with your actual form page URL
    });

    it('should format currency field with commas and two decimal places on valid input', () => {
        cy.get('input[name="currencyField"]') // Replace with your actual input field selector
            .type('1234567.89')
            .blur(); // Trigger formatting on blur

        cy.get('input[name="currencyField"]')
            .should('have.value', '1,234,567.89');
    });

    it('should not format currency field on invalid input', () => {
        cy.get('input[name="currencyField"]')
            .type('invalid input')
            .blur(); // Trigger formatting on blur

        cy.get('input[name="currencyField"]')
            .should('have.value', 'invalid input');
    });
});
